"use client";
/* Mole, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Mole(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("mole"); }, []);
  return React.createElement("piix-pal", { "pal": "mole", ...piixAttrs(props) });
}

export default Mole;
